import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import {
  Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, AudioLines, BarChart3, Check, CheckCircle2,
  ChevronRight, CircleAlert, Clipboard, CreditCard, Globe2, LayoutDashboard, Loader2, LockKeyhole,
  LogOut, Menu, Plus, RefreshCw, Search, Settings2, ShieldCheck, Trash2, Users, Wallet, X,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { API_URL, ApiError, body, readSession, request, saveSession } from './api';
import { estimateCost } from './cost';
import type { CostInputs, Pricing } from './cost';
import type { Capabilities, Group, GroupDetails, Invitation, Member, Overview, Plan, Session, Usage, User, View } from './types';

const languages = [ ['ta', 'Tamil · தமிழ்'], ['bn', 'Bengali · বাংলা'], ['hi', 'Hindi · हिन्दी'], ['or', 'Odia · ଓଡ଼ିଆ'], ['en', 'English'], ['te', 'Telugu · తెలుగు'], ['ml', 'Malayalam · മലയാളം'], ['kn', 'Kannada · ಕನ್ನಡ'], ['mr', 'Marathi · मराठी'], ['gu', 'Gujarati · ગુજરાતી'], ['pa', 'Punjabi · ਪੰਜਾਬੀ'], ['ur', 'Urdu · اردو'] ];
const languageName = (code: string) => languages.find(([key]) => key === code)?.[1].split(' · ')[0] || code;
const number = (value: number) => new Intl.NumberFormat('en-IN', { maximumFractionDigits: 1 }).format(value);
const usd = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 4 }).format(value);
const inr = (value: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);
const errorMessage = (error: unknown) => error instanceof Error ? error.message : 'Something went wrong. Please try again.';
const nav: { id: View; title: string; icon: LucideIcon }[] = [
  { id: 'overview', title: 'Overview', icon: LayoutDashboard }, { id: 'groups', title: 'Groups', icon: Users },
  { id: 'members', title: 'Members', icon: Globe2 }, { id: 'usage', title: 'Usage & costs', icon: BarChart3 },
  { id: 'providers', title: 'Provider health', icon: Activity }, { id: 'plans', title: 'Plans & billing', icon: CreditCard },
  { id: 'privacy', title: 'Privacy & account', icon: ShieldCheck },
];

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' | 'blue' | 'red' }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}
function Empty({ icon: Icon = Users, title, text, action }: { icon?: LucideIcon; title: string; text: string; action?: ReactNode }) {
  return <div className="empty"><div className="empty-icon"><Icon size={28} /></div><h3>{title}</h3><p>{text}</p>{action}</div>;
}
function Notice({ children, tone = 'amber' }: { children: ReactNode; tone?: 'amber' | 'blue' | 'red' }) {
  return <div className={`notice notice-${tone}`}><CircleAlert size={19} /><div>{children}</div></div>;
}
function Metric({ label, value, note, icon: Icon, tone = 'blue' }: { label: string; value: string; note: string; icon: LucideIcon; tone?: string }) {
  return <article className="metric"><div className="metric-top"><span>{label}</span><span className={`metric-icon ${tone}`}><Icon size={19} /></span></div><strong>{value}</strong><p>{note}</p></article>;
}
function Dialog({ title, children, close }: { title: string; children: ReactNode; close: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { ref.current?.showModal(); }, []);
  return <dialog ref={ref} onCancel={close} className="dialog"><div className="dialog-head"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="Close dialog"><X size={20} /></button></div>{children}</dialog>;
}

function Login({ onLogin }: { onLogin: (session: Session) => void }) {
  const [displayName, setName] = useState('');
  const [language, setLanguage] = useState('en');
  const [adminKey, setKey] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function login(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try { onLogin(await request<Session>('/auth/dev', undefined, { method: 'POST', ...body({ displayName: displayName.trim(), language, ...(adminKey ? { adminKey } : {}) }) })); }
    catch (error) { setError(errorMessage(error)); } finally { setBusy(false); }
  }
  return <main className="login-page"><section className="login-story"><img src="/logo.png" className="login-logo" alt="Mine2YourLingo. My Voice. Your Language." /><Badge tone="blue"><Globe2 size={13} /> TEAM COMMUNICATION, MADE SIMPLE</Badge><h1>Every voice.<br />One connected team.</h1><p>Manage your multilingual workspace, keep an eye on usage, and help conversations move forward.</p><div className="conversation-art" aria-hidden="true"><div className="language-bubble bubble-tamil">வணக்கம் <span>Tamil</span></div><div className="voice-orbit"><AudioLines size={54} /></div><div className="language-bubble bubble-bengali">নমস্কার <span>Bengali</span></div><div className="art-footnote"><ShieldCheck size={17} /> Private groups. Clear permissions.</div></div><div className="login-caption">Built for people who work together.<span>My Voice. Your Language.</span></div></section><section className="login-panel"><div className="login-form-wrap"><div className="eyebrow">WORKSPACE CONSOLE</div><h2>Welcome to your workspace</h2><p>Start a local development session to explore your connected API.</p><Notice><strong>Development authentication</strong><br />This simulator is for local testing. Phone and email sign-in require a configured production provider.</Notice><form onSubmit={login}><label>Your display name<input value={displayName} onChange={e => setName(e.target.value)} required minLength={2} maxLength={80} autoComplete="name" placeholder="e.g. Karthikeyan" /></label><label>Your language<select value={language} onChange={e => setLanguage(e.target.value)}>{languages.map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select></label><details className="admin-key"><summary>Administrator access</summary><p>Enter the configured development admin key to access system aggregates.</p><label>Development admin key<input type="password" value={adminKey} onChange={e => setKey(e.target.value)} autoComplete="off" placeholder="Configured on the API server" /></label></details>{error && <Notice tone="red">{error}</Notice>}<button className="button primary full" disabled={busy || displayName.trim().length < 2}>{busy ? <Loader2 className="spin" size={18} /> : <ArrowRight size={18} />}{busy ? 'Connecting…' : 'Start development session'}</button></form><div className="connection-note"><span className="status-dot muted" />API: {API_URL}</div><p className="login-security"><LockKeyhole size={15} /> Sessions stay in this browser tab. Provider secrets stay on the server.</p></div></section></main>;
}

export default function App() {
  const [session, setSession] = useState<Session | null>(() => readSession());
  const [view, setView] = useState<View>('overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [groups, setGroups] = useState<Group[] | null>(null);
  const [usage, setUsage] = useState<Usage | null>(null);
  const [plans, setPlans] = useState<Plan[] | null>(null);
  const [capabilities, setCapabilities] = useState<Capabilities | null>(null);
  const [overview, setOverview] = useState<Overview | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [lastUpdated, setUpdated] = useState<Date | null>(null);
  const [toast, setToast] = useState('');
  const [modal, setModal] = useState<'create' | 'join' | 'edit' | 'invite' | 'deleteGroup' | 'leaveGroup' | 'deleteAccount' | null>(null);
  const [selectedId, setSelectedId] = useState('');
  const [details, setDetails] = useState<GroupDetails | null>(null);
  const [detailError, setDetailError] = useState('');
  const [detailLoading, setDetailLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [busy, setBusy] = useState(false);
  const [invitation, setInvitation] = useState<Invitation | null>(null);
  const refreshPromise = useRef<Promise<Session> | null>(null);
  const currentUser = useRef(session?.user.id); currentUser.current = session?.user.id;
  const detailGeneration = useRef(0);
  const updateSession = useCallback((next: Session | null) => { saveSession(next); setSession(next); }, []);
  const api = useCallback(async <T,>(path: string, options: RequestInit = {}): Promise<T> => {
    if (!session) throw new ApiError(401, 'Please sign in again.');
    try { return await request<T>(path, session.accessToken, options); }
    catch (error) {
      if (!(error instanceof ApiError) || error.status !== 401) throw error;
      let next: Session;
      try {
        refreshPromise.current ||= request<Session>('/auth/refresh', undefined, { method: 'POST', ...body({ refreshToken: session.refreshToken }) });
        const tokens = await refreshPromise.current;
        next = { ...session, ...tokens, user: tokens.user || session.user };
        updateSession(next);
      } catch { updateSession(null); throw new ApiError(401, 'Your session expired. Please sign in again.'); }
      finally { refreshPromise.current = null; }
      try { return await request<T>(path, next.accessToken, options); }
      catch (retryError) { if (retryError instanceof ApiError && retryError.status === 401) updateSession(null); throw retryError; }
    }
  }, [session, updateSession]);

  const load = useCallback(async () => {
    if (!session) return;
    setLoading(true);
    const requests: [string, () => Promise<unknown>][] = [
      ['groups', () => api<Group[]>('/groups')], ['usage', () => api<Usage>('/usage')], ['plans', () => api<Plan[]>('/plans')],
      ['capabilities', () => api<Capabilities>('/capabilities')], ['profile', () => api<User>('/users/me')],
      ...(session.user.isAdmin ? [['overview', () => api<Overview>('/admin/overview')] as [string, () => Promise<unknown>]] : []),
    ];
    const results = await Promise.allSettled(requests.map(([, call]) => call()));
    if (currentUser.current !== session.user.id) return;
    const nextErrors: Record<string, string> = {};
    let succeeded = false;
    results.forEach((result, index) => {
      const key = requests[index][0];
      if (result.status === 'rejected') { nextErrors[key] = errorMessage(result.reason); return; }
      succeeded = true;
      if (key === 'groups') setGroups(result.value as Group[]);
      if (key === 'usage') setUsage(result.value as Usage);
      if (key === 'plans') setPlans(result.value as Plan[]);
      if (key === 'capabilities') setCapabilities(result.value as Capabilities);
      if (key === 'overview') setOverview(result.value as Overview);
    });
    setErrors(nextErrors); if (succeeded) setUpdated(new Date()); setLoading(false);
  }, [api, session]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 7000); return () => clearTimeout(timer); } }, [toast]);
  const loadDetails = useCallback(async (id: string) => {
    const generation = ++detailGeneration.current; const userId = currentUser.current;
    setDetails(null); setDetailError(''); setDetailLoading(true);
    try { const next = await api<GroupDetails>(`/groups/${encodeURIComponent(id)}`); if (generation === detailGeneration.current && userId === currentUser.current) setDetails(next); }
    catch (error) { if (generation === detailGeneration.current && userId === currentUser.current) setDetailError(errorMessage(error)); }
    finally { if (generation === detailGeneration.current && userId === currentUser.current) setDetailLoading(false); }
  }, [api]);
  useEffect(() => { if (selectedId && (view === 'groups' || view === 'members')) void loadDetails(selectedId); }, [selectedId, view, loadDetails]);
  useEffect(() => { if (groups && !groups.some(group => group.id === selectedId)) { setSelectedId(groups[0]?.id || ''); setDetails(null); } }, [groups, selectedId]);

  if (!session) return <Login onLogin={next => { updateSession(next); setGroups(null); setUsage(null); setOverview(null); setCapabilities(null); setPlans(null); setUpdated(null); setErrors({}); setSelectedId(''); setDetails(null); setToast(''); setModal(null); }} />;
  const user = session.user;
  const groupRole = details?.members?.find(member => member.userId === user.id)?.role;
  const canManage = groupRole === 'admin';
  const canInvite = canManage || groupRole === 'moderator';
  const page = nav.find(item => item.id === view)!;
  const connected = lastUpdated !== null && Object.keys(errors).length === 0;
  const closeModal = () => { setModal(null); setInvitation(null); };
  async function mutate(call: () => Promise<unknown>, success: string, refreshDetails = false) {
    setBusy(true);
    try { await call(); setToast(success); closeModal(); await load(); if (refreshDetails && selectedId) await loadDetails(selectedId); }
    catch (error) { setToast(errorMessage(error)); } finally { setBusy(false); }
  }
  async function logout() {
    setBusy(true);
    try { await api('/auth/logout', { method: 'POST' }); updateSession(null); }
    catch (error) { setToast(`${errorMessage(error)} The server could not confirm session revocation.`); }
    finally { setBusy(false); }
  }
  async function exportData() {
    setBusy(true);
    try {
      const data = await api('/privacy/export');
      const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
      const link = document.createElement('a'); link.href = url; link.download = `mine2yourlingo-export-${new Date().toISOString().slice(0, 10)}.json`; link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000); setToast('Your account export has been downloaded.');
    } catch (error) { setToast(errorMessage(error)); } finally { setBusy(false); }
  }
  const action = <button className="button primary" onClick={() => setModal('create')}><Plus size={17} />Create group</button>;
  const errorBlock = (key: string) => errors[key] && <Notice tone="red">{errors[key]} <button className="text-button" onClick={() => void load()}>Retry</button></Notice>;
  const groupSelect = <label className="select-label">Group<select value={selectedId} onChange={event => setSelectedId(event.target.value)}><option value="" disabled>Select a group</option>{groups?.map(group => <option value={group.id} key={group.id}>{group.name}</option>)}</select></label>;

  return <div className="app-shell">{mobileNav && <button className="nav-backdrop" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}<aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}><a className="brand" href="#overview" onClick={event => { event.preventDefault(); setView('overview'); setMobileNav(false); }}><img src="/logo.png" alt="Mine2YourLingo" /></a><div className="workspace-label"><span className="workspace-icon"><AudioLines size={20} /></span><div>Workspace console<small>{user.isAdmin ? 'System administrator' : 'Group workspace'}</small></div><Badge tone="amber">DEV</Badge></div><div className="nav-label">WORKSPACE</div><nav aria-label="Main navigation">{nav.map(({ id, title, icon: Icon }) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} aria-current={view === id ? 'page' : undefined} onClick={() => { setView(id); setMobileNav(false); setSearch(''); }}><Icon size={19} /><span>{title}</span>{view === id && <ChevronRight size={15} />}</button>)}</nav><div className="sidebar-card"><span className="sidebar-card-icon"><Globe2 size={22} /></span><strong>My Voice. Your Language.</strong><p>Connect people through the language they know best.</p><button className="text-button" onClick={() => setView('providers')}>View system readiness <ArrowUpRight size={15} /></button></div><div className="sidebar-bottom"><ShieldCheck size={15} />Private by design<span>v0.1 · Development</span></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={() => setMobileNav(true)} aria-label="Open navigation"><Menu size={22} /></button><span>Workspace</span><ChevronRight size={14} /><strong>{page.title}</strong></div><div className="topbar-right"><span className={`connection ${connected ? '' : 'connection-warning'}`}><span className={`status-dot ${connected ? '' : 'amber-dot'}`} />{loading ? 'Syncing…' : connected ? 'API connected' : lastUpdated ? 'Partial connection' : 'Not connected'}</span><button className="profile-button" onClick={() => setView('privacy')} aria-label="Open your account"><span className="avatar">{user.displayName.slice(0, 1).toUpperCase()}</span><span>{user.displayName}<small>{user.isAdmin ? 'Administrator' : 'Member'}</small></span></button></div></header><main className="content"><div className="page-heading"><div><div className="eyebrow">MINE2YOURLINGO CONSOLE</div><h1>{page.title}</h1><p>{{ overview: 'A clear view of your people, conversations, and service readiness.', groups: 'Bring people together, one private group at a time.', members: 'See who is connected and manage permissions in your groups.', usage: 'Know what you use. Understand what it costs.', providers: 'Understand which services are ready for your next conversation.', plans: 'Explore configured allowances and commercial readiness.', privacy: 'Your account, your data, and the controls that protect them.' }[view]}</p></div><button className="button secondary" disabled={loading} onClick={() => void load()}><RefreshCw size={16} className={loading ? 'spin' : ''} />Refresh</button></div>{Object.keys(errors).length > 0 && <Notice tone="red">Some data could not be refreshed. Previously loaded values may be stale. Use Refresh to retry.</Notice>}

  {view === 'overview' && <><section className="hero"><div><Badge tone="blue"><AudioLines size={13} /> BETTER COMMUNICATION STARTS HERE</Badge><h2>Different languages.<br />Shared understanding.</h2><p>Your team’s conversations, with a clear view of permissions, usage, and readiness.</p><div className="hero-actions">{action}<button className="button hero-secondary" onClick={() => setView('providers')}>Check readiness <ArrowRight size={16} /></button></div></div><div className="hero-art" aria-hidden="true"><span className="hero-bubble hero-bubble-one">தமிழ்</span><div className="hero-mic"><AudioLines size={51} /></div><span className="hero-bubble hero-bubble-two">বাংলা</span><span className="hero-bubble hero-bubble-three">हिन्दी</span><span className="hero-bubble hero-bubble-four">ଓଡ଼ିଆ</span><div className="orbit orbit-one" /><div className="orbit orbit-two" /></div></section>{!user.isAdmin && <Notice tone="blue">You are viewing your own workspace. System aggregates require a server-authorized administrator session.</Notice>}{errorBlock('overview')}<div className="metrics-grid">{user.isAdmin ? <><Metric label="Registered users" value={overview ? number(overview.users) : '—'} note={overview ? `${number(overview.activeUsers)} active today (UTC)` : 'Awaiting system aggregates'} icon={Users} /><Metric label="Groups" value={overview ? number(overview.groups) : '—'} note={overview ? `${number(overview.activeGroups)} active today (UTC)` : 'Awaiting system aggregates'} icon={Globe2} tone="teal" /><Metric label="Messages" value={overview ? number(overview.messages) : '—'} note={overview ? `${number(overview.failedMessages)} failed messages` : 'Awaiting system aggregates'} icon={AudioLines} tone="amber" /><Metric label="Estimated AI cost" value={overview ? usd(overview.estimatedAiCostUsd) : '—'} note="Recorded provider cost estimates" icon={Wallet} tone="purple" /></> : <><Metric label="Your groups" value={groups ? number(groups.length) : '—'} note="Private groups you belong to" icon={Users} /><Metric label="Your messages" value={usage ? number(usage.messages) : '—'} note={usage ? `Usage month: ${usage.month}` : 'Awaiting usage data'} icon={AudioLines} tone="teal" /><Metric label="Audio minutes" value={usage ? number(usage.audioSeconds / 60) : '—'} note="Recorded processing usage" icon={Activity} tone="amber" /><Metric label="Estimated AI cost" value={usage ? usd(usage.estimatedCostUsd) : '—'} note="Your recorded cost ledger" icon={Wallet} tone="purple" /></>}</div><div className="two-columns"><section className="card"><div className="card-heading"><div><h2>Your groups</h2><p>Private spaces for a connected team.</p></div><button className="text-button" onClick={() => setView('groups')}>View all <ArrowRight size={15} /></button></div>{errorBlock('groups')}{groups?.length ? <div className="compact-list">{groups.slice(0, 4).map(group => <button className="group-list-item" key={group.id} onClick={() => { setSelectedId(group.id); setView('groups'); }}><span className="group-symbol"><Users size={21} /></span><span><strong>{group.name}</strong><small>{number(group.memberCount)} {group.memberCount === 1 ? 'member' : 'members'} · {group.role}</small></span><ChevronRight size={18} /></button>)}</div> : <Empty title={loading ? 'Loading your groups…' : 'Your first connection starts here'} text="Create a private group or join your team using an invitation." action={<button className="button secondary" onClick={() => setModal('join')}>Join a group <ArrowRight size={15} /></button>} />}</section><section className="card"><div className="card-heading"><div><h2>Service readiness</h2><p>Live configuration from your API.</p></div><span className="small-icon"><Activity size={20} /></span></div>{errorBlock('capabilities')}<div className="readiness-list">{[ ['Speech recognition', capabilities?.ai.stt], ['Translation', capabilities?.ai.translation], ['Speech synthesis', capabilities?.ai.tts], ['Billing provider', capabilities?.billing.configured] ].map(([label, ready]) => <div className="readiness-item" key={String(label)}><span className={`readiness-dot ${ready ? 'ready' : ''}`} /><strong>{label}</strong><Badge tone={ready ? 'green' : 'amber'}>{ready === undefined ? 'Unknown' : ready ? 'Configured' : 'Not configured'}</Badge></div>)}</div><div className="card-footer"><LockKeyhole size={16} /><span>No provider keys are exposed in this console.</span></div></section></div>{user.isAdmin && <div className="two-columns"><section className="card"><div className="card-heading"><div><h2>Commercial activity</h2><p>Server-reported subscriptions and revenue.</p></div><CreditCard size={22} /></div><div className="commercial-total"><strong>{overview ? overview.revenueInr === null ? 'Unavailable' : inr(overview.revenueInr) : '—'}</strong><span>{overview?.revenueNote || 'Recorded revenue'}</span></div><div className="subscription-row"><div><strong>{overview?.subscriptions.trial ?? '—'}</strong><span>Trial</span></div><div><strong>{overview?.subscriptions.active ?? '—'}</strong><span>Active</span></div><div><strong>{overview?.subscriptions.pastDue ?? '—'}</strong><span>Past due</span></div></div></section><section className="card privacy-summary"><span className="privacy-summary-icon"><ShieldCheck size={29} /></span><h2>Visibility with boundaries</h2><p>System administration shows aggregate operational data. This console does not provide a browser for private audio or transcripts.</p><button className="text-button" onClick={() => setView('privacy')}>Review privacy controls <ArrowRight size={15} /></button></section></div>}</>}

  {view === 'groups' && <>{errorBlock('groups')}<div className="toolbar"><label className="search"><Search size={18} /><input aria-label="Search your groups" value={search} onChange={event => setSearch(event.target.value)} placeholder="Search your groups…" /></label><div className="toolbar-actions"><button className="button secondary" onClick={() => setModal('join')}>Join with invitation</button>{action}</div></div>{groups?.length ? <div className="groups-layout"><div className="group-cards">{groups.filter(group => `${group.name} ${group.description || ''}`.toLowerCase().includes(search.toLowerCase())).map(group => <button className={`group-card ${selectedId === group.id ? 'selected' : ''}`} key={group.id} onClick={() => setSelectedId(group.id)}><div className="group-card-top"><span className="group-symbol"><Users size={24} /></span><Badge tone={group.role === 'admin' ? 'blue' : 'neutral'}>{group.role}</Badge></div><h3>{group.name}</h3><p>{group.description || 'A private space to communicate in your own language.'}</p><div className="group-card-bottom"><span><Users size={14} />{group.memberCount} members</span><ChevronRight size={18} /></div></button>)}{!groups.some(group => `${group.name} ${group.description || ''}`.toLowerCase().includes(search.toLowerCase())) && <Empty icon={Search} title="No matching groups" text="Try another name or clear your search." />}</div><section className="card group-detail"><div className="card-heading"><div><h2>Group details</h2><p>Only visible to authorized members.</p></div><ShieldCheck size={19} /></div>{detailLoading ? <div className="loading-block"><Loader2 className="spin" />Loading group…</div> : detailError ? <Notice tone="red">{detailError}</Notice> : details && <><h3 className="detail-title">{details.name}</h3><p className="detail-description">{details.description || 'No group description yet.'}</p><div className="detail-stat"><span>Members</span><strong>{details.members.length}</strong></div><div className="detail-stat"><span>Listening languages</span><strong>{new Set(details.members.map(member => member.listeningLanguage)).size}</strong></div><div className="language-tags">{[...new Set(details.members.map(member => member.listeningLanguage))].map(code => <Badge key={code} tone="blue">{languageName(code)}</Badge>)}</div><div className="detail-actions"><button className="button secondary full" onClick={() => setView('members')}><Users size={16} />View members</button>{canManage && <><button className="button primary full" onClick={() => setModal('invite')}><Plus size={17} />Invite people</button><button className="button secondary full" onClick={() => setModal('edit')}><Settings2 size={16} />Edit group</button><button className="button danger-ghost full" onClick={() => setModal('deleteGroup')}><Trash2 size={15} />Delete group</button></>}{canInvite && !canManage && <button className="button primary full" onClick={() => setModal('invite')}><Plus size={17} />Invite people</button>}<button className="button danger-ghost full" onClick={() => setModal('leaveGroup')}><LogOut size={15} />Leave group</button></div></>}</section></div> : <section className="card"><Empty title={loading ? 'Loading your groups…' : 'Make room for every language'} text="Create a private group for your team. Invite members and let everyone speak the language they prefer." action={action} /></section>}</>}

  {view === 'members' && <>{errorBlock('groups')}{groups?.length ? <><div className="toolbar">{groupSelect}<div className="toolbar-actions"><label className="search"><Search size={18} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Find a member…" aria-label="Search group members" /></label>{canInvite && <button className="button primary" onClick={() => setModal('invite')}><Plus size={16} />Invite member</button>}</div></div><section className="card table-card">{detailError && <Notice tone="red">{detailError}</Notice>}{detailLoading ? <div className="loading-block"><Loader2 className="spin" />Loading members…</div> : <div className="table-scroll"><table><thead><tr><th>Member</th><th>Speaks</th><th>Listens in</th><th>Permission</th>{canManage && <th>Manage</th>}</tr></thead><tbody>{details?.members.filter(member => member.displayName.toLowerCase().includes(search.toLowerCase())).map(member => <tr key={member.userId}><td><div className="member-cell"><span className="avatar avatar-small">{member.displayName.slice(0, 1).toUpperCase()}</span><span><strong>{member.displayName}{member.userId === user.id && <span className="you-label">You</span>}</strong><small>Group member</small></span></div></td><td><Badge>{languageName(member.spokenLanguage)}</Badge></td><td><Badge tone="blue">{languageName(member.listeningLanguage)}</Badge></td><td>{canManage ? <select aria-label={`Role for ${member.displayName}`} value={member.role} disabled={busy} onChange={event => void mutate(() => api(`/groups/${selectedId}/members/${member.userId}`, { method: 'PATCH', ...body({ role: event.target.value }) }), 'Member permissions updated.', true)}><option value="member">Member</option><option value="moderator">Moderator</option><option value="admin">Admin</option></select> : <Badge tone={member.role === 'admin' ? 'blue' : 'neutral'}>{member.role}</Badge>}</td>{canManage && <td><MemberRemove member={member} busy={busy} remove={() => void mutate(() => api(`/groups/${selectedId}/members/${member.userId}`, { method: 'DELETE' }), 'Member removed from this group.', true)} /></td>}</tr>)}</tbody></table>{!details?.members.some(member => member.displayName.toLowerCase().includes(search.toLowerCase())) && <Empty icon={Search} title="No members found" text="Try a different search." />}</div>}<div className="card-footer"><ShieldCheck size={16} />Permissions are enforced by the server on every change.</div></section></> : <section className="card"><Empty title="People belong in groups" text="Create or join a group to view its members and language preferences." action={action} /></section>}</>}

  {view === 'usage' && <>{errorBlock('usage')}<div className="metrics-grid"><Metric label="Messages sent" value={usage ? number(usage.messages) : '—'} note={usage ? `Month: ${usage.month}` : 'Awaiting API data'} icon={AudioLines} /><Metric label="Audio processed" value={usage ? `${number(usage.audioSeconds / 60)} min` : '—'} note="Speech recognition usage" icon={Activity} tone="teal" /><Metric label="Translation" value={usage ? number(usage.translationCharacters) : '—'} note="Characters processed" icon={Globe2} tone="amber" /><Metric label="Estimated spend" value={usage ? usd(usage.estimatedCostUsd) : '—'} note="Account cost ledger · USD" icon={Wallet} tone="purple" /></div><div className="two-columns"><section className="card"><div className="card-heading"><div><h2>Your monthly allowances</h2><p>Enforced by the API, not this browser.</p></div><BarChart3 size={21} /></div>{usage ? <><Allowance label="Messages" value={usage.messages} limit={usage.limits.monthlyMessages} /><Allowance label="Audio minutes" value={usage.audioSeconds / 60} limit={usage.limits.monthlyAudioSeconds / 60} /><Allowance label="AI budget · USD" value={usage.estimatedCostUsd} limit={usage.limits.monthlyBudgetUsd} /><div className="card-footer"><Wallet size={16} />Daily budget: {usd(usage.limits.dailyBudgetUsd)}</div></> : <Empty icon={BarChart3} title="Usage not available" text="Connect to the API to load your actual usage and limits." />}</section><section className="card cost-explanation"><div className="card-heading"><div><h2>How costs stay predictable</h2><p>Usage-based processing, with boundaries.</p></div><ShieldCheck size={21} /></div><div className="explanation-step"><span>01</span><div><strong>Translate by language</strong><p>Recipients sharing a language can share one translation.</p></div></div><div className="explanation-step"><span>02</span><div><strong>Reuse within a private scope</strong><p>Cache reuse is scoped to the conversation boundary.</p></div></div><div className="explanation-step"><span>03</span><div><strong>Enforce real budgets</strong><p>The server rejects requests exceeding configured usage and spending limits.</p></div></div></section></div><CostCalculator actualUsage={usage} /></>}

  {view === 'providers' && <>{errorBlock('capabilities')}{errorBlock('overview')}<section className="card provider-intro"><div className="provider-intro-icon"><Activity size={30} /></div><div><h2>A truthful view of service readiness</h2><p>Configured credentials do not prove end-to-end availability. Run a real voice pilot before claiming that a language pair is ready.</p></div><Badge tone="blue">LIVE API CONFIGURATION</Badge></section><div className="provider-grid">{([ ['stt', 'Speech recognition', 'Turns a recorded voice into source text.', AudioLines], ['translation', 'Translation', 'Preserves meaning between languages.', Globe2], ['tts', 'Speech synthesis', 'Produces spoken audio for a target language.', Activity] ] as const).map(([key, title, description, Icon]) => { const ready = capabilities?.ai[key]; const reported = overview?.providerHealth.find(provider => provider.name.toLowerCase().includes(key)); return <section className="card provider-card" key={key}><div className="provider-card-top"><span className={`metric-icon ${key === 'translation' ? 'teal' : key === 'tts' ? 'amber' : 'blue'}`}><Icon size={25} /></span><Badge tone={ready ? 'green' : 'amber'}>{ready === undefined ? 'Unknown' : ready ? 'Configured' : 'Not configured'}</Badge></div><h2>{title}</h2><p>{description}</p><div className="provider-card-state"><span>Reported state</span><strong>{reported?.state || (ready ? 'Configured · not verified here' : 'Unavailable')}</strong></div><div className="provider-card-footer">{ready ? <CheckCircle2 size={17} /> : <CircleAlert size={17} />}{ready ? 'Ready for a controlled integration test' : 'Configure a server-side provider'}</div></section>; })}</div><div className="two-columns"><section className="card"><div className="card-heading"><div><h2>Platform capabilities</h2><p>Reported by the running backend.</p></div><Settings2 size={20} /></div><div className="config-list"><div><span>Authentication</span><strong>{capabilities?.auth.developmentSimulator ? 'Development simulator' : capabilities?.auth.phoneOtp ? 'Phone OTP' : 'Not configured'}</strong></div><div><span>Object storage</span><strong>{capabilities?.storage.mode || 'Unknown'}</strong></div><div><span>Realtime endpoint</span><code>{capabilities?.realtime.path || 'Unknown'}</code></div><div><span>Billing</span><Badge tone={capabilities?.billing.configured ? 'green' : 'amber'}>{capabilities?.billing.configured ? 'Configured' : 'Not configured'}</Badge></div></div></section><section className="card"><div className="card-heading"><div><h2>Known limitations</h2><p>Explicit constraints reported by the API.</p></div><CircleAlert size={20} /></div>{capabilities?.limitations.length ? <ul className="limitations">{capabilities.limitations.map((limitation, index) => <li key={index}>{limitation}</li>)}</ul> : <p className="body-copy">{capabilities ? 'No limitations were returned by this API. Verify behavior in the deployment and pilot checklists.' : 'Connect to the API to load its known limitations.'}</p>}</section></div><Notice tone="blue">Provider configuration belongs on the API server. Secrets and pricing changes cannot be made through this console.</Notice></>}

  {view === 'plans' && <>{errorBlock('plans')}<Notice>These prices are configurable business hypotheses. Purchases and paid entitlement activation are unavailable in this console until a verified billing integration is implemented.</Notice><div className="plan-grid">{plans?.map((plan, index) => <section className={`card plan-card ${index === 2 ? 'plan-accent' : ''}`} key={plan.id}><div className="plan-header"><span className="plan-icon"><CreditCard size={22} /></span><Badge tone="blue">{plan.indicative ? 'Indicative' : 'Configured'}</Badge></div><h2>{plan.name}</h2><div className="plan-price">{plan.priceInr === null ? 'Custom' : inr(plan.priceInr)}{plan.priceInr !== null && <small>/ month</small>}</div><p>Configured allowances for this plan.</p><ul><li><Check size={16} />{number(plan.maxGroupMembers)} members per group</li><li><Check size={16} />{number(plan.monthlyMessages)} messages / month</li><li><Check size={16} />{number(plan.monthlyAudioSeconds / 60)} voice minutes / month</li><li><Check size={16} />{usd(plan.monthlyBudgetUsd)} AI budget / month</li><li>{plan.broadcasts ? <Check size={16} /> : <X size={16} />}{plan.broadcasts ? 'Group broadcasts included' : 'Broadcasts unavailable'}</li></ul><button className="button secondary full" disabled>Purchases unavailable</button></section>)}</div>{!plans && <section className="card"><Empty icon={CreditCard} title={loading ? 'Loading configured plans…' : 'Plans unavailable'} text="The API must return a plan catalog before allowances can be displayed." /></section>}<section className="card billing-boundary"><ShieldCheck size={27} /><div><h2>Entitlements come from verified billing</h2><p>No browser-side action can activate a paid plan. Subscription changes require server-side purchase verification, signed billing events, and reconciliation.</p></div></section></>}

  {view === 'privacy' && <><div className="two-columns"><section className="card"><div className="card-heading"><div><h2>Your profile</h2><p>Language preferences follow your account.</p></div><span className="avatar">{user.displayName.slice(0, 1).toUpperCase()}</span></div><ProfileForm user={user} busy={busy} save={async value => { setBusy(true); try { const profile = await api<User>('/users/me', { method: 'PATCH', ...body(value) }); updateSession({ ...session, user: profile }); setToast('Your profile has been updated.'); } catch (error) { setToast(errorMessage(error)); } finally { setBusy(false); } }} /></section><section className="card privacy-summary"><span className="privacy-summary-icon"><ShieldCheck size={32} /></span><h2>Your data has boundaries</h2><p>Group permissions control who can access membership and communications. The admin console shows operational aggregates without unrestricted private message access.</p><div className="privacy-points"><span><CheckCircle2 size={17} />Server-enforced group permissions</span><span><CheckCircle2 size={17} />Personal account export</span><span><CheckCircle2 size={17} />Explicit account deletion</span></div><Notice tone="blue">Cloud translation processes message content on the server and configured providers. This product does not claim end-to-end encryption.</Notice></section></div><section className="card"><div className="card-heading"><div><h2>Account controls</h2><p>Manage your personal data and this session.</p></div><LockKeyhole size={22} /></div><div className="account-control"><span className="control-icon"><ArrowDownToLine size={22} /></span><div><strong>Export your account data</strong><p>Download your profile, memberships, own messages, and usage as JSON.</p></div><button className="button secondary" disabled={busy} onClick={() => void exportData()}>Download export</button></div><div className="account-control"><span className="control-icon"><LogOut size={22} /></span><div><strong>Sign out of this session</strong><p>Revoke this refresh session on the server and clear this browser tab.</p></div><button className="button secondary" disabled={busy} onClick={() => void logout()}>Sign out</button></div><div className="account-control"><span className="control-icon danger"><Trash2 size={22} /></span><div><strong>Delete your account</strong><p>Remove your profile and eligible data. Group ownership rules may block deletion.</p></div><button className="button danger-ghost" onClick={() => setModal('deleteAccount')}>Delete account</button></div></section><div className="api-footer"><LockKeyhole size={14} /><span>Connected API: {API_URL}</span><span>Access: {user.isAdmin ? 'System administrator · aggregates only' : 'Group member'}</span></div></>}

  <footer className="content-footer"><span>Mine2YourLingo <span className="footer-dot">·</span> My Voice. Your Language.</span><span>{lastUpdated ? `Last refresh ${lastUpdated.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}` : 'No data loaded yet'} <span className="footer-dot">·</span> Development environment</span></footer></main></div>{toast && <div className="toast" role="status"><CircleAlert size={18} /><span>{toast}</span><button className="icon-button" aria-label="Dismiss notification" onClick={() => setToast('')}><X size={17} /></button></div>}

  {(modal === 'create' || modal === 'edit') && <Dialog title={modal === 'create' ? 'Create a private group' : 'Edit group'} close={closeModal}><GroupForm initial={modal === 'edit' ? details : null} busy={busy} submit={value => void mutate(() => api(modal === 'create' ? '/groups' : `/groups/${selectedId}`, { method: modal === 'create' ? 'POST' : 'PATCH', ...body(value) }), modal === 'create' ? 'Your group has been created.' : 'Group updated.', modal === 'edit')} /></Dialog>}
  {modal === 'join' && <Dialog title="Join a group" close={closeModal}><JoinForm busy={busy} submit={token => void mutate(() => api('/groups/join', { method: 'POST', ...body({ token }) }), 'You have joined the group.')} /></Dialog>}
  {modal === 'invite' && <Dialog title={`Invite people to ${details?.name || 'your group'}`} close={closeModal}><p className="body-copy">Create a secure invitation. Anyone holding this token can join until it expires; share it only with your intended team.</p>{invitation ? <div className="invitation-result"><Badge tone="green"><CheckCircle2 size={14} />Invitation created</Badge><label>Invitation token<textarea readOnly value={invitation.token} rows={3} /></label><button className="button secondary full" onClick={async () => { try { await navigator.clipboard.writeText(invitation.token); setToast('Invitation token copied.'); } catch { setToast('Clipboard is unavailable. Select and copy the token manually.'); } }}><Clipboard size={16} />Copy token</button><p>Expires {new Date(invitation.expiresAt).toLocaleString('en-IN')}</p>{invitation.joinUrl && <label>Invitation link<input readOnly value={invitation.joinUrl} /></label>}</div> : <form onSubmit={async event => { event.preventDefault(); setBusy(true); try { setInvitation(await api<Invitation>(`/groups/${selectedId}/invitations`, { method: 'POST', ...body({ expiresInHours: Number(new FormData(event.currentTarget).get('hours')) }) })); } catch (error) { setToast(errorMessage(error)); } finally { setBusy(false); } }}><label>Invitation expires in<select name="hours" defaultValue="24"><option value="1">1 hour</option><option value="24">24 hours</option><option value="72">3 days</option></select></label><button className="button primary full" disabled={busy}>{busy ? 'Creating…' : 'Create invitation'}<Plus size={17} /></button></form>}</Dialog>}
  {modal === 'deleteGroup' && <Dialog title="Delete this group?" close={closeModal}><p className="body-copy">This removes <strong>{details?.name}</strong> and its group data. This action cannot be undone.</p><ConfirmDelete expected={details?.name || ''} label="Type the group name to confirm" busy={busy} submit={() => void mutate(() => api(`/groups/${selectedId}`, { method: 'DELETE' }), 'Group deleted.')} /></Dialog>}
  {modal === 'leaveGroup' && <Dialog title="Leave this group?" close={closeModal}><p className="body-copy">You will lose access to <strong>{details?.name}</strong>. The group remains available to its other members. A sole administrator must assign another administrator first.</p><ConfirmDelete expected={details?.name || ''} label="Type the group name to confirm" buttonLabel="Leave group" busy={busy} submit={() => void mutate(() => api(`/groups/${selectedId}/leave`, { method: 'POST' }), 'You have left the group.')} /></Dialog>}
  {modal === 'deleteAccount' && <Dialog title="Permanently delete your account?" close={closeModal}><Notice tone="red">This removes your profile and eligible personal data. Export your data first if you need a copy.</Notice><ConfirmDelete expected="DELETE" label="Type DELETE to confirm" busy={busy} submit={async () => { setBusy(true); try { await api('/users/me', { method: 'DELETE', ...body({ confirmation: 'DELETE' }) }); updateSession(null); closeModal(); } catch (error) { setToast(errorMessage(error)); } finally { setBusy(false); } }} /></Dialog>}
  </div>;
}

function MemberRemove({ member, busy, remove }: { member: Member; busy: boolean; remove: () => void }) {
  const [confirm, setConfirm] = useState(false);
  return confirm ? <div className="inline-confirm"><button className="text-button text-danger" disabled={busy} onClick={() => { remove(); setConfirm(false); }}>Confirm removal</button><button className="icon-button" aria-label="Cancel removal" onClick={() => setConfirm(false)}><X size={14} /></button></div> : <button className="icon-button text-danger" disabled={busy} aria-label={`Remove ${member.displayName} from group`} onClick={() => setConfirm(true)}><Trash2 size={16} /></button>;
}
function GroupForm({ initial, busy, submit }: { initial: GroupDetails | null; busy: boolean; submit: (value: { name: string; description: string }) => void }) {
  const [name, setName] = useState(initial?.name || ''); const [description, setDescription] = useState(initial?.description || '');
  return <form onSubmit={event => { event.preventDefault(); submit({ name: name.trim(), description: description.trim() }); }}><p className="body-copy">Everyone can speak and listen in their preferred language. Group permissions keep membership private.</p><label>Group name<input autoFocus required minLength={2} maxLength={100} value={name} onChange={event => setName(event.target.value)} placeholder="e.g. Green Valley team" /></label><label>Description <span className="optional">optional</span><textarea value={description} onChange={event => setDescription(event.target.value)} rows={3} maxLength={500} placeholder="What brings this group together?" /></label><button className="button primary full" disabled={busy || name.trim().length < 2}>{busy ? 'Saving…' : initial ? 'Save changes' : 'Create group'}<ArrowRight size={16} /></button></form>;
}
function JoinForm({ busy, submit }: { busy: boolean; submit: (token: string) => void }) {
  const [token, setToken] = useState('');
  return <form onSubmit={event => { event.preventDefault(); submit(token.trim()); }}><p className="body-copy">Paste the invitation token shared by your group administrator. Expired invitations require a new token.</p><label>Invitation token<textarea autoFocus required value={token} onChange={event => setToken(event.target.value)} rows={3} placeholder="Paste your secure token here" /></label><button className="button primary full" disabled={busy || !token.trim()}>{busy ? 'Joining…' : 'Join group'}<ArrowRight size={16} /></button></form>;
}
function ConfirmDelete({ expected, label, busy, submit, buttonLabel = 'Permanently delete' }: { expected: string; label: string; busy: boolean; submit: () => void; buttonLabel?: string }) {
  const [value, setValue] = useState('');
  return <form onSubmit={event => { event.preventDefault(); if (value === expected) submit(); }}><label>{label}<input value={value} onChange={event => setValue(event.target.value)} autoComplete="off" /></label><button className="button danger-button full" disabled={busy || value !== expected}>{busy ? 'Working…' : buttonLabel}<Trash2 size={16} /></button></form>;
}
function ProfileForm({ user, busy, save }: { user: User; busy: boolean; save: (value: { displayName: string; spokenLanguage: string; listeningLanguage: string }) => Promise<void> }) {
  const [name, setName] = useState(user.displayName); const [spoken, setSpoken] = useState(user.spokenLanguage); const [listening, setListening] = useState(user.listeningLanguage);
  return <form onSubmit={event => { event.preventDefault(); void save({ displayName: name.trim(), spokenLanguage: spoken, listeningLanguage: listening }); }}><label>Display name<input required minLength={2} maxLength={80} value={name} onChange={event => setName(event.target.value)} /></label><div className="form-two"><label>I speak<select value={spoken} onChange={event => setSpoken(event.target.value)}>{languages.map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select></label><label>I listen in<select value={listening} onChange={event => setListening(event.target.value)}>{languages.map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select></label></div><button className="button primary" disabled={busy || name.trim().length < 2}>Save profile<Check size={16} /></button></form>;
}
function Allowance({ label, value, limit }: { label: string; value: number; limit: number }) {
  const percent = limit > 0 ? Math.min(100, value / limit * 100) : value > 0 ? 100 : 0;
  return <div className="allowance"><div><strong>{label}</strong><span>{number(value)} <small>/ {number(limit)}</small></span></div><div className="progress-track" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={limit > 0 ? limit : 1} aria-valuenow={Math.min(value, limit > 0 ? limit : 1)}><span style={{ width: `${percent}%` }} className={percent >= 90 ? 'near-limit' : ''} /></div><small>{percent >= 100 && limit > 0 ? 'Monthly allowance reached' : `${number(Math.max(0, limit - value))} remaining`}</small></div>;
}

function CostCalculator({ actualUsage }: { actualUsage: Usage | null }) {
  const [inputs, setInputs] = useState<CostInputs>({ sttSeconds: 0, translationCharacters: 0, ttsCharacters: 0, llmInputTokens: 0, llmOutputTokens: 0 });
  const [pricing, setPricing] = useState<Pricing>({ sttPerMinute: null, translationPerMillion: null, ttsPerMillion: null, llmInputPerMillion: null, llmOutputPerMillion: null });
  const [revenue, setRevenue] = useState('');
  const [version, setVersion] = useState('');
  const cost = estimateCost(inputs, pricing);
  const share = cost !== null && Number(revenue) > 0 ? cost / Number(revenue) * 100 : null;
  const fields: { key: keyof CostInputs; price: keyof Pricing; title: string; unit: string; rateUnit: string }[] = [
    { key: 'sttSeconds', price: 'sttPerMinute', title: 'Speech recognition', unit: 'Audio seconds', rateUnit: 'USD / minute' },
    { key: 'translationCharacters', price: 'translationPerMillion', title: 'Translation', unit: 'Characters', rateUnit: 'USD / 1M characters' },
    { key: 'ttsCharacters', price: 'ttsPerMillion', title: 'Speech synthesis', unit: 'Characters', rateUnit: 'USD / 1M characters' },
    { key: 'llmInputTokens', price: 'llmInputPerMillion', title: 'LLM fallback input', unit: 'Tokens', rateUnit: 'USD / 1M tokens' },
    { key: 'llmOutputTokens', price: 'llmOutputPerMillion', title: 'LLM fallback output', unit: 'Tokens', rateUnit: 'USD / 1M tokens' },
  ];
  return <section className="card calculator"><div className="card-heading"><div><h2>AI cost calculator</h2><p>Estimate processing costs using your provider’s current rates.</p></div><button className="button secondary" disabled={!actualUsage} onClick={() => actualUsage && setInputs({ sttSeconds: actualUsage.audioSeconds, translationCharacters: actualUsage.translationCharacters, ttsCharacters: actualUsage.ttsCharacters, llmInputTokens: 0, llmOutputTokens: 0 })}>Use my recorded usage</button></div><Notice tone="blue">Enter verified provider rates in USD. This is a planning estimate; it excludes infrastructure, storage, delivery, taxes, and currency conversion. LLM usage is not included in the account usage response and must be entered separately.</Notice><div className="calculator-table"><div className="calculator-labels"><span>Processing stage</span><span>Usage</span><span>Provider rate · USD</span></div>{fields.map(field => <div className="calculator-line" key={field.key}><strong>{field.title}</strong><label><span>{field.unit}</span><input aria-label={`${field.title} ${field.unit}`} type="number" min="0" step="1" value={inputs[field.key]} onChange={event => setInputs({ ...inputs, [field.key]: Number(event.target.value) })} /></label><label><span>{field.rateUnit}</span><input aria-label={`${field.title} ${field.rateUnit}`} type="number" min="0" step="any" placeholder="Enter provider rate" value={pricing[field.price] ?? ''} onChange={event => setPricing({ ...pricing, [field.price]: event.target.value === '' ? null : Number(event.target.value) })} /></label></div>)}</div><div className="calculator-bottom"><div className="form-two"><label>Pricing reference / version<input value={version} onChange={event => setVersion(event.target.value)} placeholder="e.g. provider sheet, reviewed 2026-10-08" /></label><label>Monthly revenue · USD<input type="number" min="0" step="any" value={revenue} onChange={event => setRevenue(event.target.value)} placeholder="Optional: compare cost to revenue" /></label></div><div className="estimate"><div><span>Estimated processing cost</span><strong>{cost === null ? 'Rates required' : cost === 0 ? 'No processing usage entered' : usd(cost)}</strong><small>{cost === null ? 'Enter a rate for each stage with nonzero usage.' : share !== null ? `${number(share)}% of entered revenue. The 10–20% goal requires pilot validation.` : 'Add revenue to assess your variable cost share.'}{version && ` Pricing reference: ${version}.`}</small></div><span className="estimate-icon"><Wallet size={25} /></span></div></div></section>;
}
